import { isReleased } from "./pointer";

/**
 * Follows one pointer on its document until it is released or cancelled:
 * `move` gets each move of that pointer, and `end` gets the release or the
 * cancel. Both listeners go when the gesture ends, through one signal, or
 * when the function it returns is called.
 */
export function followPointer(
  target: Element,
  pointerId: number,
  move: (event: PointerEvent) => void,
  end: (event: PointerEvent) => void
): () => void {
  const drag = new AbortController();
  const { signal } = drag;
  const doc = target.ownerDocument;
  doc.addEventListener(
    "pointermove",
    (event: PointerEvent) => {
      if (event.pointerId !== pointerId) {
        return;
      }
      if (isReleased(event)) {
        drag.abort();
        end(event);
        return;
      }
      move(event);
    },
    { signal }
  );
  const release = (event: PointerEvent) => {
    if (event.pointerId === pointerId) {
      drag.abort();
      end(event);
    }
  };
  doc.addEventListener("pointerup", release, { signal });
  doc.addEventListener("pointercancel", release, { signal });
  return () => drag.abort();
}

/** One pointer at a time on a control, as `createPointerLock` makes it. */
export interface PointerLock {
  /**
   * Whether a press may go on: false while another pointer drags the
   * control. Call it before the press changes anything: when the same pointer
   * presses again, its release was missed, and the drag it left ends here.
   */
  claim: (event: PointerEvent) => boolean;
  /** Follows one pointer as `followPointer` does, and holds the control until it ends. */
  follow: typeof followPointer;
}

/**
 * One pointer at a time on a control: while one drags it, a press from
 * another is ignored, so a second finger can't take the gesture over. The
 * same pointer pressing again means its release was missed: the drag it left
 * ends with that press, its listeners gone, then the press starts afresh, so
 * a lost release never leaves the control dead or followed twice.
 */
export function createPointerLock(): PointerLock {
  let held: {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  } | null = null;
  return {
    claim: (event) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (target, pointerId, move, end) => {
      const stop = followPointer(target, pointerId, move, (event) => {
        if (held?.stop === stop) {
          held = null;
        }
        end(event);
      });
      held = { end, pointerId, stop };
      return stop;
    },
  };
}

/**
 * A mouse or pen move with no button down: the press was released where this
 * page could not see it, outside the window or over a menu, so the drag it
 * belongs to is over. A touch contact always reports a button while it moves.
 */
export function isReleased(event: { buttons: number; pointerType: string }) {
  return (
    (event.pointerType === "mouse" || event.pointerType === "pen") &&
    event.buttons === 0
  );
}

import { createPointerLock } from "../../dom/gesture";
import {
  clamp,
  clampFinite,
  degToRad,
  roundToStep,
  TAU,
} from "../../shared/math";
import {
  type ChangeEventDetails,
  type CommitEventDetails,
  createChangeEventDetails,
} from "../../value/events";
import {
  type ParameterScale,
  type ParameterScaleProp,
  resolveScale,
} from "../../value/scale";
import {
  CENTER_DEAD_ZONE_MIN_PX,
  CENTER_DEAD_ZONE_REL,
  DOUBLE_TAP_MAX_MS,
  FINE_DRAG,
  pointerAngle,
  START_ANGLE,
  SWEEP_ANGLE,
  steppedValue,
  TAP_MAX_MOVE_PX,
  VERTICAL_DRAG_RANGE_PX,
  WHEEL_DELTA_EPSILON,
} from "./shared";

/** How a drag turns a knob: up and down, around its centre, or by the turns of the pointer. */
export type KnobDragMode = "circular" | "revolution" | "vertical";

/** What `onValueChange` receives with each change: the reason, the event behind it, and `cancel()` to refuse the change. */
export type KnobChangeEventDetails =
  | ChangeEventDetails<"drag", PointerEvent>
  | ChangeEventDetails<"keyboard", KeyboardEvent>
  | ChangeEventDetails<"wheel", WheelEvent>
  | ChangeEventDetails<"reset", KeyboardEvent | PointerEvent>
  | ChangeEventDetails<"input-change", Event>;
/** Why the value changed: `"drag"`, `"keyboard"`, `"wheel"`, `"input-change"` (a typed value) or `"reset"`. */
export type KnobChangeEventReason = KnobChangeEventDetails["reason"];
/** What `onValueCommitted` receives once a gesture ends: the reason and the event behind it. */
export type KnobCommitEventDetails =
  | CommitEventDetails<"drag", PointerEvent>
  | CommitEventDetails<"keyboard", KeyboardEvent>
  | CommitEventDetails<"wheel", WheelEvent>
  | CommitEventDetails<"reset", KeyboardEvent | PointerEvent>
  | CommitEventDetails<"input-change", Event>;
/** Why the value was committed: the same reasons as a change. */
export type KnobCommitEventReason = KnobCommitEventDetails["reason"];

/** The options of `createKnobController`: the value, held or controlled, its range, scale, steps and anchor, the drag mode, the formatting and the callbacks. */
export interface KnobOptions {
  /** Value the indicator arc grows from, such as `0` on a -1…1 pan. Defaults to `min`. */
  anchor?: number;
  /** Uncontrolled starting value, and what a reset returns to; defaults to the middle of the travel. */
  defaultValue?: number;
  disabled?: boolean;
  /** @default "circular" */
  dragMode?: KnobDragMode;
  /** How the value is written, e.g. `{ maximumFractionDigits: 1 }`. */
  format?: Intl.NumberFormatOptions;
  /** Step for Page Up/Page Down and Shift + arrow keys. @default 10 */
  largeStep?: number;
  locale?: Intl.LocalesArgument;
  /** @default 100 */
  max?: number;
  /** @default 0 */
  min?: number;
  onValueChange?: (value: number, details: KnobChangeEventDetails) => void;
  onValueCommitted?: (value: number, details: KnobCommitEventDetails) => void;
  /** @default "linear" */
  scale?: ParameterScaleProp;
  /** @default 1 */
  step?: number;
  /** The controlled value; leave it out for the knob to hold its own. */
  value?: number;
}

/** What a view draws a knob from. */
export interface KnobSnapshot {
  anchor: number | undefined;
  /** Indicator arc origin, 0…1 along the sweep. */
  anchorPercent: number;
  /** Rotation in degrees, clockwise from 12 o'clock. */
  angle: number;
  disabled: boolean;
  /** Whether a pointer is turning the knob. */
  dragging: boolean;
  dragMode: KnobDragMode;
  /** The value as text, with `format` and `locale`. */
  formatted: string;
  largeStep: number;
  max: number;
  min: number;
  /** Value position, 0…1 along the sweep. */
  percent: number;
  resetValue: number;
  /** How the value maps onto the dial's travel. */
  scale: ParameterScale;
  step: number;
  /** The value as displayed: the dragged one while a pointer turns the knob. */
  value: number;
}

/** What `createKnobController` returns: the snapshot to draw from, and the press, keys, wheel, typed value and reset that turn it. */
export interface KnobController {
  /** Listens to wheel steps on `element`; returns what removes the listener. */
  attachWheel: (element: HTMLElement) => () => void;
  getSnapshot: () => KnobSnapshot;
  /**
   * Handles a key on the knob's input: arrows, Page Up/Down, Home and End,
   * Shift for the large step, Delete or Backspace to reset. Returns `true`
   * when the knob takes the key, so the caller can prevent its default.
   */
  keyDown: (event: KeyboardEvent) => boolean;
  /**
   * Starts a pointer gesture on `control`: a drag turns the knob, a double
   * tap or an Alt + press resets it. The drag follows the pointer on the
   * document until it is released.
   */
  press: (event: PointerEvent, control: HTMLElement) => void;
  /** Returns to the default value, reporting a `"reset"` change and commit. */
  reset: (event: KeyboardEvent | PointerEvent) => void;
  /** Takes the latest options; call it whenever they may have changed. */
  setOptions: (options: KnobOptions) => void;
  subscribe: (listener: () => void) => () => void;
  /** Sets a typed value, on the grid, reporting an `"input-change"` change and commit. */
  type: (typed: number, event: Event) => void;
}

/** One pointer drag, from press to release. */
interface KnobGesture {
  /** Whether the gesture changed the value at least once; if so its end commits, even back on the start value. */
  changed: boolean;
  lastAngle: number;
  lastY: number;
  /** Farthest distance from the press point, in px. */
  maxDistance: number;
  /**
   * Where the drag has taken the dial along its travel, 0…1 and beyond:
   * accumulated move by move, so Shift can make any stretch of it finer,
   * and kept apart from the rounded value so small moves add up.
   */
  position: number;
  rect: DOMRect;
  startX: number;
  startY: number;
}

/**
 * A knob's behavior with no view attached: its value, held or controlled,
 * every way of turning it, and what it looks like as a snapshot.
 */
export function createKnobController(
  initial: KnobOptions = {}
): KnobController {
  let options = initial;
  const pointers = createPointerLock();
  let scale: ParameterScale = resolveScale(initial.scale ?? "linear");
  const bounds = () => ({
    max: options.max ?? 100,
    min: options.min ?? 0,
    step: options.step ?? 1,
  });
  const resetValue = () => {
    const { max, min, step } = bounds();
    return (
      options.defaultValue ??
      roundToStep(scale.toValue(0.5, min, max), step, min)
    );
  };

  let uncontrolled: number | undefined;
  // Holds the turned value until the pointer is released, so a controlled
  // value that lags behind can't pull the knob back mid-drag.
  let dragValue: number | null = null;
  let dragging = false;
  let gesture: KnobGesture | null = null;
  let lastTapAt = 0;
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  let formatter: Intl.NumberFormat | null = null;
  let formatKey: unknown[] = [];
  const format = (value: number) => {
    if (
      !formatter ||
      formatKey[0] !== options.locale ||
      formatKey[1] !== options.format
    ) {
      formatter = new Intl.NumberFormat(options.locale, options.format);
      formatKey = [options.locale, options.format];
    }
    return formatter.format(value);
  };

  const displayed = () => {
    const { max, min } = bounds();
    const held =
      options.value === undefined
        ? (uncontrolled ?? resetValue())
        : options.value;
    return dragValue ?? clampFinite(held, min, max);
  };
  const onGrid = (raw: number) => {
    const { max, min, step } = bounds();
    return clamp(roundToStep(raw, step, min), min, max);
  };

  let snapshot: KnobSnapshot | null = null;
  const getSnapshot = () => {
    const { max, min, step } = bounds();
    const value = displayed();
    const { anchor, disabled = false, largeStep = 10 } = options;
    const dragMode = options.dragMode ?? "circular";
    const formatted = format(value);
    const reset = resetValue();
    if (
      snapshot?.value === value &&
      snapshot.dragging === dragging &&
      snapshot.min === min &&
      snapshot.max === max &&
      snapshot.step === step &&
      snapshot.largeStep === largeStep &&
      snapshot.anchor === anchor &&
      snapshot.disabled === disabled &&
      snapshot.dragMode === dragMode &&
      snapshot.formatted === formatted &&
      snapshot.resetValue === reset &&
      snapshot.scale === scale
    ) {
      return snapshot;
    }
    const percent = scale.toPosition(value, min, max);
    const anchorPercent =
      anchor === undefined ? 0 : scale.toPosition(anchor, min, max);
    snapshot = {
      anchor,
      anchorPercent,
      angle: START_ANGLE + percent * SWEEP_ANGLE,
      disabled,
      dragMode,
      dragging,
      formatted,
      largeStep,
      max,
      min,
      percent,
      resetValue: reset,
      scale,
      step,
      value,
    };
    return snapshot;
  };

  /** Reports a change; keeps it unless it was canceled, and says which. */
  const change = (next: number, details: KnobChangeEventDetails) => {
    if (next === displayed()) {
      return false;
    }
    options.onValueChange?.(next, details);
    if (details.isCanceled) {
      return false;
    }
    if (options.value === undefined) {
      uncontrolled = next;
    } else if (details.reason === "drag") {
      dragValue = next;
    }
    notify();
    return true;
  };
  const commit = (next: number, details: KnobCommitEventDetails) => {
    options.onValueCommitted?.(next, details);
  };
  /** A change that is over as soon as it is made: keys, typed values, the wheel, a reset. */
  const setAtOnce = (
    next: number,
    reason: Exclude<KnobChangeEventReason, "drag">,
    event: Event
  ) => {
    const details = createChangeEventDetails(
      reason,
      event
    ) as KnobChangeEventDetails;
    if (change(next, details)) {
      commit(next, { event, reason } as KnobCommitEventDetails);
    }
  };

  /** The value a gesture has turned the knob to, after one pointer move. */
  const valueFromGesture = (current: KnobGesture, event: PointerEvent) => {
    const { max, min } = bounds();
    const speed = event.shiftKey ? FINE_DRAG : 1;
    if (options.dragMode === "vertical") {
      current.position +=
        ((current.lastY - event.clientY) / VERTICAL_DRAG_RANGE_PX) * speed;
    } else {
      const { rect } = current;
      const angle = pointerAngle(event.clientX, event.clientY, rect);
      const distance = Math.hypot(
        event.clientX - (rect.left + rect.width / 2),
        event.clientY - (rect.top + rect.height / 2)
      );
      const deadZone = Math.max(
        CENTER_DEAD_ZONE_MIN_PX,
        Math.min(rect.width, rect.height) * CENTER_DEAD_ZONE_REL
      );
      if (distance > deadZone) {
        let delta = angle - current.lastAngle;
        if (delta > Math.PI) {
          delta -= TAU;
        } else if (delta < -Math.PI) {
          delta += TAU;
        }
        const fullTurn =
          options.dragMode === "revolution" ? TAU : degToRad(SWEEP_ANGLE);
        current.position += (delta / fullTurn) * speed;
      }
      current.lastAngle = angle;
    }
    current.lastY = event.clientY;
    return scale.toValue(current.position, min, max);
  };

  /** Ends the gesture: a tap that moved little is a tap, and a second one soon after resets. */
  const finish = (end: PointerEvent, allowTap: boolean) => {
    if (!gesture) {
      return;
    }
    const current = gesture;
    gesture = null;
    dragging = false;
    const turned = displayed();
    dragValue = null;
    notify();

    if (allowTap && current.maxDistance <= TAP_MAX_MOVE_PX) {
      const now = performance.now();
      const isDoubleTap = now - lastTapAt <= DOUBLE_TAP_MAX_MS;
      lastTapAt = isDoubleTap ? 0 : now;
      if (isDoubleTap) {
        setAtOnce(resetValue(), "reset", end);
      }
      return;
    }
    lastTapAt = 0;
    if (current.changed) {
      commit(turned, { event: end, reason: "drag" });
    }
  };

  const press: KnobController["press"] = (event, control) => {
    if (options.disabled || !pointers.claim(event)) {
      return;
    }
    // Alt + click returns to the default, as in a DAW.
    if (event.altKey) {
      setAtOnce(resetValue(), "reset", event);
      return;
    }
    control.setPointerCapture?.(event.pointerId);
    const rect = control.getBoundingClientRect();
    const { min, max } = bounds();
    gesture = {
      changed: false,
      lastAngle: pointerAngle(event.clientX, event.clientY, rect),
      lastY: event.clientY,
      maxDistance: 0,
      position: scale.toPosition(displayed(), min, max),
      rect,
      startX: event.clientX,
      startY: event.clientY,
    };
    dragging = true;
    notify();

    const move = (moveEvent: PointerEvent) => {
      const current = gesture;
      if (!current) {
        return;
      }
      current.maxDistance = Math.max(
        current.maxDistance,
        Math.hypot(
          moveEvent.clientX - current.startX,
          moveEvent.clientY - current.startY
        )
      );
      if (
        change(
          onGrid(valueFromGesture(current, moveEvent)),
          createChangeEventDetails("drag", moveEvent)
        )
      ) {
        current.changed = true;
      }
    };
    // Only a release is a tap: not a cancel, when the browser took the pointer
    // away, nor the next press, when the release was missed.
    pointers.follow(control, event.pointerId, move, (end) =>
      finish(end, end.type === "pointerup" || end.type === "pointermove")
    );
  };

  const keyDown: KnobController["keyDown"] = (event) => {
    if (options.disabled) {
      return false;
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      setAtOnce(resetValue(), "reset", event);
      return true;
    }
    const { max, min, step } = bounds();
    const current = displayed();
    const largeStep = options.largeStep ?? 10;
    const stepOptions = {
      largeStep,
      max,
      min,
      scale,
      step,
    };
    const targets: Record<string, number> = {
      ArrowDown: steppedValue(current, -1, event.shiftKey, stepOptions),
      ArrowLeft: steppedValue(current, -1, event.shiftKey, stepOptions),
      ArrowRight: steppedValue(current, 1, event.shiftKey, stepOptions),
      ArrowUp: steppedValue(current, 1, event.shiftKey, stepOptions),
      End: max,
      Home: min,
      PageDown: steppedValue(current, -1, true, stepOptions),
      PageUp: steppedValue(current, 1, true, stepOptions),
    };
    const target = targets[event.key];
    if (target === undefined) {
      return false;
    }
    setAtOnce(onGrid(target), "keyboard", event);
    return true;
  };

  const attachWheel: KnobController["attachWheel"] = (element) => {
    const handle = (event: WheelEvent) => {
      if (options.disabled || event.ctrlKey || event.metaKey) {
        return;
      }
      event.preventDefault();
      if (Math.abs(event.deltaY) < WHEEL_DELTA_EPSILON) {
        return;
      }
      const { max, min, step } = bounds();
      const next = steppedValue(displayed(), event.deltaY < 0 ? 1 : -1, false, {
        largeStep: options.largeStep ?? 10,
        max,
        min,
        scale,
        step,
      });
      setAtOnce(onGrid(next), "wheel", event);
    };
    const wheel = new AbortController();
    element.addEventListener("wheel", handle, {
      passive: false,
      signal: wheel.signal,
    });
    return () => wheel.abort();
  };

  return {
    attachWheel,
    getSnapshot,
    keyDown,
    press,
    reset: (event) => setAtOnce(onGrid(resetValue()), "reset", event),
    setOptions: (next) => {
      options = next;
      scale = resolveScale(next.scale ?? "linear");
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    type: (typed, event) => setAtOnce(onGrid(typed), "input-change", event),
  };
}

import { degToRad, PI_HALF, radToDeg, TAU } from "../../shared/math";
import { type ParameterScale, resolveScale } from "../../value/scale";

/** Center of the 48×48 viewBox the arcs are drawn in. */
export const VIEWBOX_CENTER = 24;

/** Gap at the bottom of the dial: the sweep runs clockwise from bottom-left to bottom-right. */
export const ANGLE_GAP_RAD = Math.PI / 5;

/** Rotation at `min`, in degrees clockwise from 12 o'clock. */
export const START_ANGLE = 90 + radToDeg(PI_HALF + ANGLE_GAP_RAD);

/** Rotation travelled from `min` to `max`, in degrees. */
export const SWEEP_ANGLE = radToDeg(TAU - 2 * ANGLE_GAP_RAD);

/** Outer edge of the arcs in the viewBox; each stroke is centered inside it. */
export const ARC_OUTER_RADIUS = 23;

/** The width of the track and indicator arcs in the 48 by 48 view box, unless given. */
export const DEFAULT_ARC_STROKE_WIDTH = 3;

/** Vertical drag: pointer travel, in px, for the whole `min…max` range. */
export const VERTICAL_DRAG_RANGE_PX = 150;

/** Circular drag: inside this fraction of the diameter the angle is synced but not accumulated, so crossing the hub doesn't jump. */
export const CENTER_DEAD_ZONE_REL = 0.08;

/** The smallest the hub's dead zone may be, in px, however small the knob. */
export const CENTER_DEAD_ZONE_MIN_PX = 2;

/** A press that moves less than this is a tap; two quick taps reset the value. */
export const TAP_MAX_MOVE_PX = 12;

/** The longest two taps may be apart, in ms, to count as a double tap and reset the value. */
export const DOUBLE_TAP_MAX_MS = 320;

/** A wheel movement smaller than this is ignored. */
export const WHEEL_DELTA_EPSILON = 0.1;

/** Holding Shift turns the knob this much slower than the pointer moves. */
export const FINE_DRAG = 0.25;

/** With a scale that isn't linear, a key or wheel notch moves this share of the travel. */
export const POSITION_STEP = 0.01;

/** With a scale that is not linear, a large step (Shift or Page Up and Down) moves this share of the travel. */
export const LARGE_POSITION_STEP = 0.1;

/** `disabled`, `dragging` and the drag mode become data attributes; the numbers stay in `state`. */
export const STATE_ATTRIBUTES_MAPPING = {
  dragMode: (value: string) => ({ "data-drag-mode": value }),
  max: () => null,
  min: () => null,
  value: () => null,
};

/**
 * The value `direction` steps away from `current`: by `step` (or `largeStep`)
 * on a linear scale, by a share of the travel on any other, and always by at
 * least one `step`.
 */
export function steppedValue(
  current: number,
  direction: -1 | 1,
  large: boolean,
  options: {
    largeStep: number;
    max: number;
    min: number;
    scale: ParameterScale;
    step: number;
  }
): number {
  const { largeStep, max, min, scale, step } = options;
  if (scale === LINEAR) {
    return current + direction * (large ? largeStep : step);
  }
  const position =
    scale.toPosition(current, min, max) +
    direction * (large ? LARGE_POSITION_STEP : POSITION_STEP);
  const next = scale.toValue(position, min, max);
  return Math.abs(next - current) < step ? current + direction * step : next;
}

/** The linear scale, resolved once. */
export const LINEAR = resolveScale("linear");

/** SVG arc along the dial between two normalized positions (0…1). */
export function arcPath(radius: number, from: number, to: number): string {
  const point = (t: number) => {
    const angle = degToRad(START_ANGLE + t * SWEEP_ANGLE - 90);
    return {
      x: VIEWBOX_CENTER + radius * Math.cos(angle),
      y: VIEWBOX_CENTER + radius * Math.sin(angle),
    };
  };
  const start = point(from);
  const end = point(to);
  const largeArc = (to - from) * SWEEP_ANGLE > 180 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${radius} ${radius} 0 ${largeArc} 1 ${end.x} ${end.y}`;
}

/** The angle of a pointer around the centre of `rect`, in radians, 0 pointing right. */
export function pointerAngle(
  clientX: number,
  clientY: number,
  rect: DOMRect
): number {
  return Math.atan2(
    clientY - (rect.top + rect.height / 2),
    clientX - (rect.left + rect.width / 2)
  );
}

/** `value` kept within `min` and `max`. */
export const clamp = (value: number, min: number, max: number): number =>
  Math.max(min, Math.min(value, max));

/** `value` kept within 0 and 1. */
export const clampUnit = (value: number): number =>
  Math.max(0.0, Math.min(value, 1.0));

/** Clamp into `min…max`; a non-finite value (NaN from a 0/0, ±Infinity) falls back to `min`. */
export const clampFinite = (value: number, min: number, max: number): number =>
  Number.isFinite(value) ? clamp(value, min, max) : min;

/** `value` rounded to the nearest multiple of `interval`. */
export const quantizeRound = (value: number, interval: number): number =>
  Math.round(value / interval) * interval;

/** Snap to `step` with `min` as the origin, without float noise (0.1 + 0.2). */
export function roundToStep(value: number, step: number, min: number): number {
  const decimals = (String(step).split(".")[1] ?? "").length;
  return Number(
    (Math.round((value - min) / step) * step + min).toFixed(decimals)
  );
}

/** A full turn in radians: 2π. */
export const TAU = Math.PI * 2.0;
/** A quarter turn in radians: π/2. */
export const PI_HALF = Math.PI / 2.0;

/** An angle in radians, in degrees. */
export const radToDeg = (rad: number): number => (rad * 180.0) / Math.PI;

/** An angle in degrees, in radians. */
export const degToRad = (deg: number): number => (deg / 180.0) * Math.PI;

/** A point on two axes. */
export type Point = { x: number; y: number };

/**
 * What a change reports: why it happened (`reason`), the event behind it, the
 * element that triggered it, and `cancel()` to refuse the change. Every input
 * of every controller, the wheel included, reaches its callbacks in this one
 * shape.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  allowPropagation: () => void;
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  readonly isPropagationAllowed: boolean;
  reason: Reason;
  trigger: Element | undefined;
}

/** What a commit reports once a gesture ends: why it happened (`reason`) and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it and `allowPropagation()` to let the event go on. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  let propagationAllowed = false;
  return {
    allowPropagation: () => {
      propagationAllowed = true;
    },
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    get isPropagationAllowed() {
      return propagationAllowed;
    },
    reason,
    trigger:
      event.currentTarget instanceof Element ? event.currentTarget : undefined,
  };
}

import { clamp } from "../shared/math";

/**
 * How a value maps onto a control's travel, and back. `toPosition` gives
 * where `value` sits along the travel, from 0 at `min` to 1 at `max`;
 * `toValue` is its inverse.
 */
export interface ParameterScale {
  toPosition: (value: number, min: number, max: number) => number;
  toValue: (position: number, min: number, max: number) => number;
}

/** Even steps: the right feel for levels, times and anything heard in differences. */
export const LINEAR_SCALE: ParameterScale = {
  toPosition: (value, min, max) =>
    clamp((value - min) / (max - min || 1), 0, 1),
  toValue: (position, min, max) => min + clamp(position, 0, 1) * (max - min),
};

/**
 * Even ratios: the right feel for frequency, Q, ratios and times heard in
 * proportions, where a linear sweep hides the useful range in its first few
 * degrees. Needs a positive `min`; below that it falls back to linear.
 */
export const LOGARITHMIC_SCALE: ParameterScale = {
  toPosition: (value, min, max) => {
    if (!(min > 0 && max > min)) {
      return LINEAR_SCALE.toPosition(value, min, max);
    }
    const clamped = clamp(value, min, max);
    return Math.log(clamped / min) / Math.log(max / min);
  },
  toValue: (position, min, max) => {
    if (!(min > 0 && max > min)) {
      return LINEAR_SCALE.toValue(position, min, max);
    }
    return min * (max / min) ** clamp(position, 0, 1);
  },
};

/** A scale as an option takes it: `"linear"`, `"log"`, or a scale of your own. */
export type ParameterScaleProp = "linear" | "log" | ParameterScale;

/** The scale an option names: `"linear"` and `"log"` as `LINEAR_SCALE` and `LOGARITHMIC_SCALE`, a scale of your own as it is. */
export function resolveScale(scale: ParameterScaleProp): ParameterScale {
  if (scale === "log") {
    return LOGARITHMIC_SCALE;
  }
  return scale === "linear" ? LINEAR_SCALE : scale;
}

import { definePrimitive as definePrimitiveOf } from "@ui-sdk/core";

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`piano-roll-note`, `timeline-track-header`), and a component that gives
 * its own name to a part (`timeline-time-selection`) keeps it: the kernel
 * writes its own, which this replaces by the one the part was given.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

