import {
  ARC_OUTER_RADIUS,
  arcPath,
  createKnobController,
  DEFAULT_ARC_STROKE_WIDTH,
  type KnobController,
  type KnobOptions,
  type KnobSnapshot,
  START_ANGLE,
  SWEEP_ANGLE,
} from "../../core/primitives/knob/index";
import {
  css,
  type PrimitiveInstance,
  type PropSpec,
